import socket
import concurrent.futures

def scan(ip):
    res = []
    for port in [80, 8080, 5000, 8000, 3000]:
        s = socket.socket()
        s.settimeout(0.2)
        try:
            s.connect((ip, port))
            res.append((ip, port))
        except:
            pass
        finally:
            s.close()
    return res

ips = [f'192.168.80.{i}' for i in range(1, 255)]
with concurrent.futures.ThreadPoolExecutor(max_workers=50) as ex:
    for r in ex.map(scan, ips):
        if r:
            print(r)
